// Extract TopEng booking payload
const payload = $input.first().json.body || $input.first().json;

const roomName = payload.roomName || 'Phòng họp lớn';
const locationName = payload.locationName || 'Hà Nội';
const date = payload.date || payload.formattedDate;
const startTime = payload.startTime || '10:00';
const endTime = payload.endTime || '11:00';
const purpose = payload.purpose || 'Họp nội bộ TopEng';
const booker = payload.booker || {};
const bookerName = booker.name || payload.bookerName || 'Thành viên TopEng';
const team = booker.team || payload.team || 'R&D';

// Construct message for Telegram / Slack
const telegramMessage = `🏢 *[TOPENG - LỊCH HỌP MỚI ĐƯỢC TẠO]*\n\n` +
  `📍 *Phòng:* ${roomName} (${locationName})\n` +
  `📅 *Ngày họp:* ${date}\n` +
  `⏰ *Thời gian:* ${startTime} - ${endTime}\n` +
  `🎯 *Nội dung:* ${purpose}\n` +
  `👤 *Người đặt:* ${bookerName} (${team})\n\n` +
  `⚡ _Tự động điều phối qua TopEng AI Assistant & n8n Workflow_`;

// Construct event for Google Calendar
return [{
  json: {
    ...payload,
    summary: `[Họp TopEng] ${purpose} - ${roomName}`,
    description: `Cuộc họp được đặt tự động qua Trợ lý AI TopEng.\nNgười đặt: ${bookerName} (${team})\nPhòng họp: ${roomName} - ${locationName}`,
    startDateTime: `${payload.date || '2026-09-01'}T${startTime}:00+07:00`,
    endDateTime: `${payload.date || '2026-09-01'}T${endTime}:00+07:00`,
    location: `${roomName}, Văn phòng ${locationName}`,
    telegramMessage: telegramMessage
  }
}];
